&lt;h3 style=&quot;line-height: 1;&quot;&gt;&lt;strong&gt;Required Skills/Abilities:&amp;nbsp;&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Previous experience in the construction or heavy equipment industry a plus&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Previous or current experience with budgeting&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Knowledge of excel the use of spreadsheets&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Must possess exceptional customer service, organization and time management and communication skills&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At least 2+ years of Parts management/supervisory experience&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 style=&quot;line-height: 1;&quot;&gt;&lt;strong&gt;Education and Experience:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
