&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Graduation from a qualified nursing program&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt; color: rgb(204, 9, 47);&quot;&gt;&lt;strong&gt;How we prepare our LPNs for success&lt;/strong&gt;&lt;strong&gt;:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Paid training from day 1 in the office, in the home, and online&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Practice with award-winning adult and pediatric Simulation labs&lt;/span&gt;&lt;/li&gt;
